import React from 'react'
import './community.css'
import communityImage from '../../images/Group.png';
import communityImage2 from '../../images/Group2.png';

function Community() {
  return (
    <section class="communityContainer">
        <img src={communityImage} alt="Community" className='img1' />

        <div className='contentContainer'>
            <h1 className='title'>Komünite</h1>
            <p className='text'>Teknoloji Komünitesi ile hayalindeki işi bulabilir, kendini geliştirecek eğitimlere katılabilir ve teknoloji uzmanlarıyla tanışabilirsin!</p>
            <Stack spacing={2} direction="row" sx={{marginTop: "10px"}}>
        <Button 
          variant="contained" 
          sx={{
            backgroundColor: "#00B666", 
            color: "#FFFFFF", 
            textTransform: "none",
            width: "192px", 
            height: "48px" 
          }} 
          onClick={() => window.open('https://www.techcareer.net/dictionary', '_blank')}
        >
          Kullanmak İçin Tıkla
        </Button>
      </Stack>
        </div>
    </section>
  )
}

export default Community
